     ensures
         match result {
             Ok(frame) => frame.inv(),
             Err(_) => true,
         },
 )]
 pub(super) fn alloc() -> Result<FrameAddress, Error> {
     instance().alloc()
 }

 /// # Description
 ///
 /// Allocates `count` physically contiguous frames.
