     requires
         count > 0,
     ensures
         match result {
             Ok(base) => {
                 &&& base.inv()
                 &&& base@ + (count as int) * spec_page_size() <= usize::MAX as int
             },
             Err(_) => true,
         },
 )]
 pub(super) fn alloc_contiguous(count: usize) -> Result<FrameAddress, Error> {
     instance().alloc_contiguous(count)
 }

