     instance().free(frame)
 }

 ///
 /// # Description
 ///
 /// Checks whether the frame allocator tracks the frame at the given physical address.
 ///
 /// # Returns
 ///
 /// Returns `true` when the frame allocator tracks the frame at `phys_addr`.
